"""Standalone Beeline agent, generated by tools/bundle_agent.py."""

# --- agent_core/__init__.py ---
"""Beeline campaign agent core: priors -> Bayesian posterior -> pilots -> allocation."""

# --- agent_core/priors.py ---
"""Priors on the base effect (ratio at channel multiplier 1.0) per (cell, target).

cell = (current_tariff, arpu_segment). The source is pluggable: call
set_prior_source(fn) with fn(cell, target) -> (mean, sd) to replace the default.
"""

WEAK_MEAN = 0.0
WEAK_SD = 0.1


def weak_prior(cell, target):
    return WEAK_MEAN, WEAK_SD


_source = weak_prior


def set_prior_source(fn):
    global _source
    _source = fn if fn is not None else weak_prior


def get_prior(cell, target):
    return _source(cell, target)

# --- agent_core/priors_history.py ---
"""History prior on the base effect per (cell, target), from data/change_tariff.csv.

Base effect = relative ARPU change x conversion at channel multiplier 1.0.
History is only a hint (judge effects differ from it), so the mean is shrunk
toward 0 and the sd is kept wide. Definitions: docs/PRIORS.md.

Plug in:  set_prior_source(priors_history.get_prior)
"""

import math
from pathlib import Path

import pandas as pd

DATA_PATH = Path(__file__).resolve().parent / "data" / "change_tariff.csv"

LOW_MAX = 1000.0      # arpu_segment thresholds from the case guide (ARPU_3m_avg)
MID_MAX = 5000.0
MIN_PREV_ARPU = 50.0  # below this the relative change is dominated by the tiny denominator
PCT_CAP = 5.0         # relative change clipped to [-1, PCT_CAP]; tail beyond ~p95 is noise
SHRINK_K = 30.0       # pseudo-count: mean is scaled by n / (n + SHRINK_K)
SD_FLOOR = 0.05
UNSEEN_SD = 0.1       # no history for (cell, target): same as priors.weak_prior


def arpu_segment(arpu):
    if arpu < LOW_MAX:
        return "LOW"
    if arpu <= MID_MAX:
        return "MID"
    return "HIGH"


def load_table(path=DATA_PATH):
    """{(from_tariff, arpu_segment, to_tariff): {n, mean, std, conv}}; {} if unreadable."""
    try:
        df = pd.read_csv(path, usecols=["AVG_ARPU_PREV_3M", "AVG_ARPU_NEXT_3M",
                                        "tariff_plan_code_from", "tariff_plan_code_to"])
    except (OSError, ValueError):
        return {}

    df = df[df["AVG_ARPU_PREV_3M"] >= MIN_PREV_ARPU].copy()
    if df.empty:
        return {}
    df["segment"] = df["AVG_ARPU_PREV_3M"].map(arpu_segment)
    df["pct"] = ((df["AVG_ARPU_NEXT_3M"] - df["AVG_ARPU_PREV_3M"])
                 / df["AVG_ARPU_PREV_3M"]).clip(-1.0, PCT_CAP)

    keys = ["tariff_plan_code_from", "segment", "tariff_plan_code_to"]
    g = df.groupby(keys).agg(n=("pct", "size"), mean=("pct", "mean"),
                             std=("pct", "std")).reset_index()
    # Conversion proxy: share of switchers from (from, segment) that went to this
    # target, Laplace-smoothed over all targets seen in history.
    n_targets = df["tariff_plan_code_to"].nunique()
    total = g.groupby(["tariff_plan_code_from", "segment"])["n"].transform("sum")
    g["conv"] = (g["n"] + 1) / (total + n_targets)

    return {
        (r.tariff_plan_code_from, r.segment, r.tariff_plan_code_to): {
            "n": int(r.n),
            "mean": float(r.mean),
            "std": 0.0 if pd.isna(r.std) else float(r.std),
            "conv": float(r.conv),
        }
        for r in g.itertuples(index=False)
    }


def prior_from_stats(stats):
    """(mean, sd) of the base effect for one history row of load_table()."""
    n, conv = stats["n"], stats["conv"]
    raw = conv * stats["mean"]
    mean = raw * n / (n + SHRINK_K)
    se = conv * stats["std"] / math.sqrt(n)
    # Judge effects differ from history: uncertainty at least the size of the effect itself.
    sd = max(SD_FLOOR, math.sqrt(se * se + raw * raw))
    return mean, sd


def make_prior_source(table):
    def source(cell, target):
        stats = table.get((cell[0], cell[1], target))
        if stats is None:
            return 0.0, UNSEEN_SD
        return prior_from_stats(stats)
    return source


_default = None


def get_history_prior(cell, target):
    global _default
    if _default is None:
        _default = make_prior_source(load_table())
    return _default(cell, target)

# --- agent_core/cells.py ---
"""Audience cells = (current_tariff, arpu_segment) with size and mean predicted ARPU."""


def build_cells(profile):
    g = (profile.groupby(["current_tariff", "arpu_segment"], observed=True)
         .agg(size=("ID_NUMBER", "size"), arpu=("predicted_arpu", "mean"))
         .reset_index())
    return {
        (r.current_tariff, r.arpu_segment): {"size": int(r.size), "arpu": float(r.arpu)}
        for r in g.itertuples(index=False)
    }

# --- agent_core/bayes.py ---
"""Normal-normal posterior on the base effect per (cell, target).

A pilot on channel ch observes ratio = base * mult_ch + N(0, 0.804 / sqrt(n)),
so in base-effect units: obs = ratio / mult, sd = 0.804 / (sqrt(n) * mult).
"""

import math


PILOT_NOISE = 0.804


class Posterior:
    def __init__(self):
        self._state = {}  # (cell, target) -> (mean, var)
        self.n_obs = {}   # (cell, target) -> pilots observed
        self.n_total = {} # (cell, target) -> customers observed over all pilots

    def get(self, cell, target):
        key = (cell, target)
        if key not in self._state:
            mean, sd = get_prior(cell, target)
            self._state[key] = (mean, sd * sd)
        mean, var = self._state[key]
        return mean, math.sqrt(var)

    def update(self, cell, target, observed_ratio, n, mult):
        mean, sd = self.get(cell, target)
        obs = observed_ratio / mult
        obs_var = (PILOT_NOISE / (math.sqrt(n) * mult)) ** 2
        prec = 1.0 / (sd * sd) + 1.0 / obs_var
        new_var = 1.0 / prec
        new_mean = new_var * (mean / (sd * sd) + obs / obs_var)
        self._state[(cell, target)] = (new_mean, new_var)
        self.n_obs[(cell, target)] = self.n_obs.get((cell, target), 0) + 1
        self.n_total[(cell, target)] = self.n_total.get((cell, target), 0) + n
        return new_mean, math.sqrt(new_var)

    def lcb(self, cell, target, k=1.0):
        mean, sd = self.get(cell, target)
        return mean - k * sd

    def ucb(self, cell, target, k=1.0):
        mean, sd = self.get(cell, target)
        return mean + k * sd

    def confirmed_enough(self, cell, target, min_pilots=2, min_n=300):
        key = (cell, target)
        return self.n_obs.get(key, 0) >= min_pilots or self.n_total.get(key, 0) >= min_n

# --- agent_core/planner.py ---
"""Final campaigns: greedy allocation of confident-positive cells under reach/money caps."""

MAX_PER_CAMPAIGN = 5000
MAX_CAMPAIGNS = 10
FINAL_K = 1.5  # final only if mean - FINAL_K * sd > 0


def _channel_options(base_mean, arpu, channels):
    """Expected net per contact on every channel for a given base effect."""
    return {ch: base_mean * c["conversion_multiplier"] * arpu - c["cost_per_contact"]
            for ch, c in channels.items()}


def _contacts(size, cost, reach_left, money_left):
    n = min(size, MAX_PER_CAMPAIGN, reach_left)
    if cost > 0:
        n = min(n, int(money_left // cost))
    return max(n, 0)


class Planner:
    def __init__(self, env, cells, posterior, pilot_log):
        self.env = env
        self.cells = cells
        self.post = posterior
        self.pilot_log = pilot_log

    def _tested(self):
        return {((p["current_tariff"], p["arpu_segment"]), p["target_tariff"])
                for p in self.pilot_log}

    def qualifying(self):
        """Per cell: the confirmed target with LCB > 0 and the highest posterior mean."""
        best = {}
        for cell, target in self._tested():
            mean, sd = self.post.get(cell, target)
            if not self.post.confirmed_enough(cell, target) or mean - FINAL_K * sd <= 0:
                continue
            if cell not in best or mean > best[cell][1]:
                best[cell] = (target, mean)
        return best

    def plan(self):
        channels = self.env.channels
        reach_left = self.env.max_total_contacts - sum(p["n"] for p in self.pilot_log)
        money_left = self.env.total_budget - sum(p["cost"] for p in self.pilot_log)

        options = []
        for cell, (target, mean) in self.qualifying().items():
            per_contact = _channel_options(mean, self.cells[cell]["arpu"], channels)
            best_pc = max(per_contact.values())
            if best_pc > 0:
                options.append((best_pc, cell, target, per_contact))
        options.sort(key=lambda x: x[0], reverse=True)

        campaigns = []
        for _, cell, target, per_contact in options:
            if len(campaigns) >= MAX_CAMPAIGNS or reach_left <= 0:
                break
            size = self.cells[cell]["size"]
            # channel with the best expected total net given what is left
            best = None
            for ch, pc in per_contact.items():
                if pc <= 0:
                    continue
                cost = channels[ch]["cost_per_contact"]
                n = _contacts(size, cost, reach_left, money_left)
                if n > 0 and (best is None or n * pc > best[0]):
                    best = (n * pc, ch, n, pc)
            if best is None:
                continue
            _, ch, n, pc = best
            reach_left -= n
            money_left -= n * channels[ch]["cost_per_contact"]
            campaigns.append({
                "campaign_name": f"{cell[0]}_{cell[1]}_to_{target}_{ch}",
                "filter_current_tariff": cell[0],
                "filter_arpu_segment": cell[1],
                "target_tariff": target,
                "channel": ch,
                "_per_contact": pc,
                "_contacts": n,
            })

        campaigns.sort(key=lambda c: c["_per_contact"], reverse=True)
        for c in campaigns:
            del c["_per_contact"], c["_contacts"]

        if not campaigns:
            campaigns = [self._fallback()]
        return campaigns

    def _fallback(self):
        """Nothing is confident: one small push campaign on the best-posterior cell."""
        tested = self._tested()
        if tested:
            cell, target = max(tested, key=lambda ct: self.post.get(*ct)[0])
        else:
            cell = max(self.cells, key=lambda c: self.cells[c]["size"])
            targets = [t for t in self.env.tariffs["tariff_plan_code"] if t != cell[0]]
            target = targets[0]
        profile = self.env.customer_profile
        sub = profile[(profile["current_tariff"] == cell[0])
                      & (profile["arpu_segment"] == cell[1])]
        smallest = sub["data_segment"].value_counts().idxmin() if len(sub) else None
        return {
            "campaign_name": f"fallback_{cell[0]}_{cell[1]}_to_{target}_push",
            "filter_current_tariff": cell[0],
            "filter_arpu_segment": cell[1],
            "filter_data_segment": smallest,
            "target_tariff": target,
            "channel": "push",
        }

# --- agent_core/explorer.py ---
"""Pilot phase: pick single-cell sms pilots, feed results into the posterior."""


MIN_CELL_SIZE = 300
ROUND1_PILOTS = 10
ROUND1_PER_CELL = 2
ROUND1_N = 150
ROUND2_N = 200
PILOT_CHANNEL = "sms"


class Explorer:
    def __init__(self, env, cells, posterior):
        self.env = env
        self.cells = cells
        self.post = posterior
        self.log = []  # our own record of every pilot incl. filters

    def candidates(self):
        """Round-1 arms: cells by value (size x mean ARPU), best targets by prior mean."""
        targets = list(self.env.tariffs["tariff_plan_code"])
        big = [c for c, info in self.cells.items() if info["size"] >= MIN_CELL_SIZE]
        big.sort(key=lambda c: self.cells[c]["size"] * self.cells[c]["arpu"], reverse=True)
        out = []
        for cell in big:
            ranked = sorted((t for t in targets if t != cell[0]),
                            key=lambda t: self.post.get(cell, t)[0], reverse=True)
            out.extend((cell, t) for t in ranked[:ROUND1_PER_CELL])
        return out

    def _can_pilot(self, n):
        cost = self.env.channels[PILOT_CHANNEL]["cost_per_contact"]
        return (self.env.pilots_left > 0 and self.env.remaining_contacts >= 10
                and self.env.remaining_budget >= cost * min(n, 10))

    def pilot(self, cell, target, n):
        tariff, segment = cell
        try:
            res = self.env.run_pilot(target_tariff=target, channel=PILOT_CHANNEL,
                                     n_customers=n, filter_current_tariff=tariff,
                                     filter_arpu_segment=segment)
        except (RuntimeError, ValueError):
            return None
        mult = self.env.channels[PILOT_CHANNEL]["conversion_multiplier"]
        mean, sd = self.post.update(cell, target, res["observed_lift_ratio"],
                                    res["n_customers"], mult)
        self.log.append({
            "current_tariff": tariff, "arpu_segment": segment, "target_tariff": target,
            "channel": PILOT_CHANNEL, "n": res["n_customers"], "cost": res["cost"],
            "observed_ratio": res["observed_lift_ratio"], "post_mean": mean, "post_sd": sd,
        })
        return res

    def run(self):
        # Round 1: top candidates by prior UCB x cell value.
        for cell, target in self.candidates()[:ROUND1_PILOTS]:
            if not self._can_pilot(ROUND1_N):
                break
            self.pilot(cell, target, ROUND1_N)

        # Round 2: confirm round-1 leaders (mean > 0) until they pass or fail the final gate.
        tested = {(p["current_tariff"], p["arpu_segment"], p["target_tariff"]) for p in self.log}
        while self._can_pilot(ROUND2_N):
            open_leaders = []
            for tariff, segment, target in tested:
                cell = (tariff, segment)
                mean, sd = self.post.get(cell, target)
                if mean <= 0:
                    continue
                if self.post.confirmed_enough(cell, target) and mean - FINAL_K * sd > 0:
                    continue
                info = self.cells[cell]
                open_leaders.append((mean * info["size"] * info["arpu"], cell, target))
            if not open_leaders:
                break
            open_leaders.sort(key=lambda x: x[0], reverse=True)
            _, cell, target = open_leaders[0]
            if self.pilot(cell, target, ROUND2_N) is None:
                break
        return self.log

# --- agent.py ---
"""Beeline campaign agent: explore with single-cell pilots, exploit confident cells."""



class Agent:
    def act(self, env):
        set_prior_source(get_history_prior)
        cells = build_cells(env.customer_profile)
        post = Posterior()
        explorer = Explorer(env, cells, post)
        pilot_log = explorer.run()
        self.pilot_log = pilot_log
        return Planner(env, cells, post, pilot_log).plan()
